INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist das Erstellen des Lastenhefts nach DIN 69901-5 Teil der Planung?', 2, '[{"text": "Ja", "correct": true, "because": "Definiert Anforderungen früh"}, {"text": "Nein", "correct": false, "because": "Es gehört zur Planung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel hat das Lastenheft nach DIN 69901-5?', 3, '[{"text": "Anforderungen des Auftraggebers festlegen", "correct": true, "because": "Basis für Projekt"}, {"text": "Kosten direkt senken", "correct": false, "because": "Kein primäres Ziel"}, {"text": "Teamstruktur definieren", "correct": false, "because": "Anderer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das Lastenheft beschreibt den Soll-Zustand. b) Es wird erst nach Projektstart erstellt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Planung ist entscheidend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Inhalte gehören nach DIN 69901-5 ins Lastenheft?', 4, '[{"text": "Zieldefinition", "correct": true, "because": "Beschreibt Soll-Zustand"}, {"text": "Unklare Vorgaben", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Funktionale Anforderungen", "correct": true, "because": "Spezifizieren Funktionen"}, {"text": "Qualitätsanforderungen", "correct": true, "because": "Definieren Standards"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Projekt ohne Lastenheft nach DIN 69901-5 geplant werden?', 2, '[{"text": "Nein", "correct": true, "because": "Anforderungen unklar"}, {"text": "Ja", "correct": false, "because": "Risiko von Missverständnissen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Lastenheft ist nach DIN 69901-5 schlecht formuliert?', 3, '[{"text": "Irgendwas soll besser sein", "correct": true, "because": "Zu vage"}, {"text": "App mit Login bis 30. Juni", "correct": false, "because": "Klar und spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das Lastenheft nach DIN 69901-5 nur für IT-Projekte relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Gilt für alle Projekte"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Aspekt ist nach DIN 69901-5 im Lastenheft zentral?', 3, '[{"text": "Klar definierte Anforderungen", "correct": true, "because": "Vermeidet Unklarheit"}, {"text": "Teamzusammensetzung", "correct": false, "because": "Kein Fokus"}, {"text": "Kostenübersicht", "correct": false, "because": "Späterer Schritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das Lastenheft dient als Basis für das Pflichtenheft. b) Es ist optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne Lastenheft nach DIN 69901-5?', 3, '[{"text": "Anforderungen bleiben unklar", "correct": true, "because": "Fehlende Basis"}, {"text": "Projekt wird schneller", "correct": false, "because": "Eher Verzögerung"}, {"text": "Kosten sinken", "correct": false, "because": "Missverständnisse möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann das Lastenheft nach DIN 69901-5 vage formuliert sein?', 2, '[{"text": "Nein", "correct": true, "because": "Klarheit erforderlich"}, {"text": "Ja", "correct": false, "because": "Widerspricht Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt ein Lastenheft nach DIN 69901-5?', 3, '[{"text": "Software mit 3 Modulen bis Q3", "correct": true, "because": "Spezifisch definiert"}, {"text": "Irgendwas entwickeln", "correct": false, "because": "Zu ungenau"}, {"text": "Team soll etwas bauen", "correct": false, "because": "Nicht konkret"}]'),
('000000 admittedly00-0000-0000-0000-000000000000', 'Ist das Lastenheft nach DIN 69901-5 nur für den Auftraggeber relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Auftragnehmer braucht es"}, {"text": "Ja", "correct": false, "because": "Beide Seiten betroffen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören nach DIN 69901-5 ins Lastenheft?', 4, '[{"text": "Nicht-funktionale Anforderungen", "correct": true, "because": "Definieren Qualität"}, {"text": "Vage Wünsche", "correct": false, "because": "Fehlt Präzision"}, {"text": "Leistungsanforderungen", "correct": true, "because": "Spezifizieren Funktion"}, {"text": "Abnahmebedingungen", "correct": true, "because": "Regeln Übergabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss das Lastenheft nach DIN 69901-5 dokumentiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Nachweis erforderlich"}, {"text": "Nein", "correct": false, "because": "Dokumentation essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt das Lastenheft nach DIN 69901-5?', 3, '[{"text": "Vertragliche Grundlage schaffen", "correct": true, "because": "Regelt Anforderungen"}, {"text": "Zeitplan festlegen", "correct": false, "because": "Anderer Fokus"}, {"text": "Team motivieren", "correct": false, "because": "Kein primäres Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann das Lastenheft ohne Kundeninput erstellt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Kundenanforderungen nötig"}, {"text": "Ja", "correct": false, "because": "Risiko von Fehlern"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor erschwert das Erstellen des Lastenhefts?', 3, '[{"text": "Unklare Kundenwünsche", "correct": true, "because": "Verhindern Klarheit"}, {"text": "Gute Kommunikation", "correct": false, "because": "Fördert Erstellung"}, {"text": "Klarer Zeitrahmen", "correct": false, "because": "Unterstützt Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das Lastenheft spezifiziert Anforderungen. b) Es enthält die Lösung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Lösung im Pflichtenheft"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nutzen des Lastenhefts nach DIN 69901-5?', 3, '[{"text": "Missverständnisse vermeiden", "correct": true, "because": "Klarheit schaffen"}, {"text": "Zeit verlängern", "correct": false, "because": "Kein Ziel"}, {"text": "Kosten direkt senken", "correct": false, "because": "Unabhängig davon"}]');
